"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[7473],{7473:e=>{e.exports=JSON.parse('{"concept":"Prime Number Patterns","subject":"mathematics","category":"Number Theory","explanation":"Prime numbers follow interesting patterns that help in eleven-plus exams. Key insights: All primes except 2 are odd. Primes greater than 3 end in 1, 3, 7, or 9. Twin primes are pairs that differ by 2 (like 11 and 13). Prime gaps get larger as numbers increase. Understanding these patterns helps solve probability and sequence problems.","examples":[{"question":"If I pick a prime number at random, what\'s the probability it\'s even?","solution":"Very small - only if I pick 2","explanation":"Only 2 is an even prime. All other primes are odd because even numbers (except 2) are divisible by 2, making them composite."},{"question":"List all twin prime pairs between 10 and 20.","solution":"11,13 and 17,19","explanation":"Twin primes are primes that differ by 2. Between 10-20: primes are 11, 13, 17, 19. Twin pairs: (11,13) and (17,19)."},{"question":"What\'s the next prime after 23?","solution":"29","explanation":"Check each number: 24 (even), 25 (5\xb2), 26 (even), 27 (3\xb3), 28 (even), 29 (prime - only divisible by 1 and 29)."}],"exercises":[{"type":"multiple-choice","question":"How many prime numbers end in the digit 5?","options":["None","One","Two","Many"],"correct":[1],"explanation":"Only 5 itself is prime and ends in 5. All other numbers ending in 5 are divisible by 5, making them composite."},{"type":"multiple-choice","question":"Which is NOT a twin prime pair?","options":["3, 5","5, 7","7, 11","11, 13"],"correct":[2],"explanation":"Twin primes differ by exactly 2. Here: 3,5 (diff=2), 5,7 (diff=2), 7,11 (diff=4), 11,13 (diff=2). So 7,11 is not a twin prime pair."},{"type":"open-ended","question":"Sarah says \'All odd numbers greater than 2 are prime.\' Give a counterexample to prove her wrong.","sample_answer":"9 is odd and greater than 2, but 9 = 3 \xd7 3, so it\'s composite, not prime.","explanation":"Many odd numbers are composite: 9, 15, 21, 25, 27, 33, etc."}],"tips":["Remember: 2 is the only even prime","Primes > 3 must end in 1, 3, 7, or 9","To test if a number is prime, only check divisibility up to its square root","Twin primes always have exactly one even number between them"]}')}}]);